The proposed direction is right; this is the sharpened version. Do NOT use `#[tauri::command(async)]` on the sync fn (it runs on a tokio worker and `fetch_script`'s `block_on` would panic "Cannot start a runtime from within a runtime"); use `async fn` + `spawn_blocking`, and keep the filesystem probe inside the closure as well:

```rust
/// Scans the active workspace's `artifacts/` folder. ... Runs on a worker (file copies and CDN
/// fetches, up to 100 MB and 20 s a script), never the window's thread; a tick that finds the last
/// scan still running does nothing instead of queueing behind it.
#[tauri::command]
pub async fn artifacts_scan(app: tauri::AppHandle, path: String, project: Option<String>) -> Result<usize, String> {
    use tauri::{Emitter, Manager};
    tauri::async_runtime::spawn_blocking(move || {
        let workspace = PathBuf::from(path);
        if !workspace.is_absolute() || !workspace.is_dir() || on_network_share(&workspace) {
            return Ok(0);
        }
        let mut seen = match SCANNED.get_or_init(Default::default).try_lock() {
            Ok(g) => g,
            Err(std::sync::TryLockError::WouldBlock) => return Ok(0),
            Err(std::sync::TryLockError::Poisoned(p)) => p.into_inner(),
        };
        let changed = scan_workspace(app.state::<Library>().inner(), &workspace, project, &|u| fetch_script(&app, u), &mut seen);
        if changed > 0 {
            let _ = app.emit(crate::capture::EVENT, ());
        }
        Ok(changed)
    })
    .await
    .map_err(|e| e.to_string())?
}
```

