/// Async and off the async workers (like `artifact_add`): the scan copies files of up to MAX_FILE
/// and fetches a page's CDN scripts with a 20 s timeout each, none of which may hold the window's
/// thread. A scan that finds one already running returns 0; the page's next tick retries.
#[tauri::command]
pub async fn artifacts_scan(app: tauri::AppHandle, path: String, project: Option<String>) -> Result<usize, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let workspace = PathBuf::from(path);
        if !workspace.is_absolute() || !workspace.is_dir() || on_network_share(&workspace) {
            return Ok(0);
        }
        use tauri::{Emitter, Manager};
        let lib = app.state::<Library>();
        let changed = {
            let mut seen = match SCANNED.get_or_init(Default::default).try_lock() {
                Ok(seen) => seen,
                Err(std::sync::TryLockError::WouldBlock) => return Ok(0),
                Err(std::sync::TryLockError::Poisoned(e)) => return Err(e.to_string()),
            };
            scan_workspace(lib.inner(), &workspace, project, &|u| fetch_script(&app, u), &mut seen)
        };
        if changed > 0 {
            let _ = app.emit(crate::capture::EVENT, ());
        }
        Ok(changed)
    })
    .await
    .map_err(|e| e.to_string())?
}

Notes: the path checks (is_dir, on_network_share/GetDriveTypeW) also move inside spawn_blocking since a stat on a disconnected drive blocks too; lib.rs registration and the page's invoke name/args are unchanged; verified to compile and pass `cargo test --lib artifacts::tests` (13 passed) in a worktree of the PR branch. A regression test in the repo's existing style would assert `include_str!("artifacts.rs").contains("pub async fn artifacts_scan(")` (cf. agents.rs:1617), since an AppHandle is not available to unit tests here.
